    if (!target) throw new Error(`${file}: stop "${heading}" missing "target"`)
    if (!code) throw new Error(`${file}: stop "${heading}" missing "code"`)

    // read prose (blank line, then text until next ## or end)
    while (i < lines.length && lines[i].trim() === '') i++
