import { check } from '../dist/check.js'
import { join, resolve } from 'node:path'
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const dir = fileURLToPath(new URL('../', import.meta.url))
const demoDir = resolve(dir, '../docugate-demo')
const screenFile = join(demoDir, 'frontend/src/screens/InvoiceDetail.tsx')
const original = readFileSync(screenFile, 'utf8')

// Simulate rename: data-tour="invoice-total" -> data-tour="invoice-total-RENAMED"
const modified = original.replace('data-tour="invoice-total"', 'data-tour="invoice-total-RENAMED"')
writeFileSync(screenFile, modified)

try {
  const result = check(demoDir, '.')
  const tourWarns = result.warnings.filter((w) => w.file?.startsWith('.docugate/tour/') && !w.message.includes('front matter') && !w.message.includes('Title'))
  console.log('Tour check warnings after rename:', JSON.stringify(tourWarns, null, 2))
  if (tourWarns.some((w) => /invoice-total/.test(w.message))) {
    console.log('PASS: warning produced for renamed invoice-total')
    process.exit(0)
  } else {
    console.log('FAIL: no warning for renamed invoice-total')
    process.exit(1)
  }
} finally {
  writeFileSync(screenFile, original)
  console.log('Restored InvoiceDetail.tsx')
}

