import { check } from '../dist/check.js'
import { join, resolve } from 'node:path'
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const dir = fileURLToPath(new URL('../', import.meta.url))
const demoDir = resolve(dir, '../docugate-demo')
const screenFile = join(demoDir, 'frontend/src/screens/InvoiceDetail.tsx')
const original = readFileSync(screenFile, 'utf8')

// --- Test 1: Before rename, check should produce no tour-specific warnings ---
const before = check(demoDir, '.')
const beforeTour = before.warnings.filter(
  (w) => w.file?.startsWith('.docugate/tour/') && /invoice-total/.test(w.message),
)
if (beforeTour.length === 0) {
  console.log('PASS: no tour warning before rename')
} else {
  console.log('FAIL: unexpected warning before rename:', beforeTour)
  process.exit(1)
}

// --- Test 2: After rename, check should warn about invoice-total ---
const modified = original.replace('data-tour="invoice-total"', 'data-tour="invoice-total-RENAMED"')
writeFileSync(screenFile, modified)

try {
  const after = check(demoDir, '.')
  const afterTour = after.warnings.filter(
    (w) => w.file?.startsWith('.docugate/tour/') && /invoice-total/.test(w.message),
  )
  if (afterTour.length > 0) {
    console.log('PASS: warning produced after rename:', afterTour.map((w) => w.message).join('; '))
    process.exit(0)
  } else {
    console.log('FAIL: no warning after renaming invoice-total. All warnings:')
    console.log(JSON.stringify(after.warnings, null, 2))
    process.exit(1)
  }
} finally {
  writeFileSync(screenFile, original)
  console.log('Restored InvoiceDetail.tsx')
}

