  }
})

test('serializeTourFile emits correct structure', () => {
  const tour = {
    route: '/items/:id',
    title: 'Item',
    stops: [
      { heading: 'Name', target: '[data-tour="item-name"]', code: 'src/Item.tsx', prose: 'The name.' },
    ],
  }
