// Parsing
// ---------------------------------------------------------------------------

test('parseTourFile reads front matter and stops', () => {
  const file = join(FIXTURES, 'tour-parse/simple.md')
  const text = readFileSync(file, 'utf8')
  const tour = parseTourFile(text, 'simple.md')

  assert.equal(tour.route, '/invoices/:id')
